head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onheadermouseout]<br/>Header Cell 영역에서 마우스 포인터가 나갔을때 발생합니다.",
    "validation" : [
        "Header Cell 영역에서 마우스 포인터가 나갔을때 onheadermouseout 이벤트가 발생해야 합니다.",
        "Header 영역 내에서 마우스 포인터가 다른 Header Cell 로 넘어간 경우도 발생합니다.",
        "info 파라미터로 마우스가 나간 Header Cell 과 마우스가 들어간 Header Cell 의 ID 가 객체로 전달되어야 합니다.",
        "info.newHeaderId 는 마우스가 들어간 Header Cell 의 ID 값을 가지며, 마우스가 다른 Header Cell 로 이동한 경우가 아니면 null 값을 갖습니다.",
        "RowNum, RowStauts Column 의 Header 영역에서도 이벤트가 발생해야 합니다.",        
        "Header Cell 에서 GridView 영역 밖에서 마우스가 나가면 onheadermouseout > ongridmouseleave 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (RowNum / RowStatus Header 표시 고정)
    let grp_comp = $c.gcm.getTestGroup();

    let strTarget = '';
    strTarget += '<w2:gridView ' + $c.gcm.getNameSpace() + ' dataList="data:dlt_bind" autoFit="allColumn" rowNumVisible="true" rowStatusVisible="true" rowNumHeaderValue="No." rowStatusHeaderValue="St." ev:onheadermouseout="scwin.target1_onheadermouseout" ev:ongridmouseleave="scwin.target1_ongridmouseleave" checkAllType="false" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        "gridView",
        strTarget,
        grp_comp
    );
}



// Header Cell 영역에서 마우스가 나갈 때 발생
//  - info 객체 자체는 한 줄로 출력
//  - info.newHeaderId / oldHeaderId / header_id / id 는 각각 개별 라인으로 출력
scwin.target1_onheadermouseout = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onheadermouseout=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newHeaderId : " + info.newHeaderId);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldHeaderId : " + info.oldHeaderId);
    wf_body_bottom.getObj("scwin").setReturnValue("info.header_id : " + info.header_id);
    wf_body_bottom.getObj("scwin").setReturnValue("info.id : " + info.id);
}



// GridView 영역 밖으로 마우스가 나갈 때 발생 (발생 순서 관찰용)
scwin.target1_ongridmouseleave = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_ongridmouseleave=====");
}
